    int distinctEchoSubstrings(string text) {
        int n = text.size();
        unordered_set<string> seen;
        for (int i = 0; i < n; i++)
            for (int L = 1; i + 2 * L <= n; L++)
                if (text.compare(i, L, text, i + L, L) == 0)
                    seen.insert(text.substr(i, 2 * L));
        return seen.size();
    }
};

