class Solution:
    def distinctEchoSubstrings(self, text: str) -> int:
        n = len(text)
        MOD = (1 << 61) - 1
        B = 131
        h = [0] * (n + 1)
        p = [1] * (n + 1)
        for i, c in enumerate(text):
            h[i + 1] = (h[i] * B + ord(c)) % MOD
            p[i + 1] = p[i] * B % MOD
        def get(i, j):
            return (h[j] - h[i] * p[j - i]) % MOD
        res = set()
        for i in range(n):
            for L in range(1, (n - i) // 2 + 1):
                if get(i, i + L) == get(i + L, i + 2 * L):
                    res.add((get(i, i + 2 * L), L))
        return len(res)

