class Solution {
public:
    int distinctEchoSubstrings(string text) {
        int n = text.size();
        const unsigned long long MOD = (1ULL << 61) - 1, B = 131;
        vector<unsigned long long> h(n + 1, 0), p(n + 1, 1);
        auto mulmod = [&](unsigned long long a, unsigned long long b) {
            __uint128_t c = (__uint128_t)a * b;
            return (unsigned long long)(c % MOD);
        };
        for (int i = 0; i < n; i++) {
            h[i + 1] = (mulmod(h[i], B) + text[i]) % MOD;
            p[i + 1] = mulmod(p[i], B);
        }
        auto get = [&](int i, int j) {
            return (h[j] + MOD - mulmod(h[i], p[j - i])) % MOD;
        };
        unordered_set<unsigned long long> res;
        for (int i = 0; i < n; i++)
            for (int L = 1; i + 2 * L <= n; L++)
                if (get(i, i + L) == get(i + L, i + 2 * L))
                    res.insert(get(i, i + 2 * L) * 2001 + L);
        return res.size();
    }
};

