class Solution {
    public int distinctEchoSubstrings(String text) {
        int n = text.length();
        final long MOD = (1L << 61) - 1, B = 131;
        long[] h = new long[n + 1], p = new long[n + 1];
        p[0] = 1;
        for (int i = 0; i < n; i++) {
            h[i + 1] = (java.math.BigInteger.valueOf(h[i]).multiply(java.math.BigInteger.valueOf(B))
                    .add(java.math.BigInteger.valueOf(text.charAt(i))))
                    .mod(java.math.BigInteger.valueOf(MOD)).longValue();
            p[i + 1] = java.math.BigInteger.valueOf(p[i]).multiply(java.math.BigInteger.valueOf(B))
                    .mod(java.math.BigInteger.valueOf(MOD)).longValue();
        }
        java.util.function.BiFunction<Integer, Integer, Long> get = (i, j) ->
                ((h[j] - java.math.BigInteger.valueOf(h[i]).multiply(java.math.BigInteger.valueOf(p[j - i]))
                        .mod(java.math.BigInteger.valueOf(MOD)).longValue()) % MOD + MOD) % MOD;
        Set<Long> res = new HashSet<>();
        for (int i = 0; i < n; i++)
            for (int L = 1; i + 2 * L <= n; L++)
                if (get.apply(i, i + L).equals(get.apply(i + L, i + 2 * L)))
                    res.add(get.apply(i, i + 2 * L) * 2001 + L);
        return res.size();
    }
}

